// Exact minimum monotone FORMULA leaves for a target bitvector, over a lattice generated by n generators.
// usage: fdp K maxstates n g0 g1 ... g_{n-1} T   (hex uint64)
// prints: per-level counts; "MIN k" and a witness formula, or "NONE<=K"
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
typedef uint64_t u64;
static u64 *key; static uint32_t *lft,*rgt; static uint8_t *opc,*lv; static uint32_t nf=0;
static uint32_t *ht; static u64 hmask;
static u64 hh(u64 x){x^=x>>33;x*=0xff51afd7ed558ccdULL;x^=x>>33;x*=0xc4ceb9fe1a85ec53ULL;x^=x>>33;return x;}
static long find(u64 x){u64 h=hh(x)&hmask;while(ht[h]){if(key[ht[h]-1]==x)return ht[h]-1;h=(h+1)&hmask;}return -1;}
static void ins(u64 x,uint32_t id){u64 h=hh(x)&hmask;while(ht[h])h=(h+1)&hmask;ht[h]=id+1;}
static void pr(uint32_t id){ if(opc[id]=='v'){printf("x%u",lft[id]);return;} printf("(");pr(lft[id]);printf(opc[id]=='&'?"&":"|");pr(rgt[id]);printf(")");}
int main(int argc,char**argv){
  int K=atoi(argv[1]); long maxs=atol(argv[2]); int n=atoi(argv[3]);
  u64 T=strtoull(argv[4+n],0,16);
  int hb=1; while((1L<<hb)<2*maxs) hb++; hmask=(1ULL<<hb)-1;
  ht=calloc(1ULL<<hb,4); key=malloc(maxs*8); lft=malloc(maxs*4); rgt=malloc(maxs*4); opc=malloc(maxs); lv=malloc(maxs);
  uint32_t start[80],end[80];
  start[1]=0;
  for(int i=0;i<n;i++){u64 g=strtoull(argv[4+i],0,16); if(find(g)>=0) continue; key[nf]=g;lft[nf]=i;opc[nf]='v';lv[nf]=1;ins(g,nf);nf++;}
  end[1]=nf;
  long f=find(T); if(f>=0){printf("MIN 1\n");pr(f);printf("\n");return 0;}
  for(int k=2;k<=K;k++){
    start[k]=nf;
    for(int i=1;i<=k/2;i++){int j=k-i;
      for(uint32_t a=start[i];a<end[i];a++){ uint32_t b0=(i==j)?a:start[j];
        for(uint32_t b=b0;b<end[j];b++){
          u64 x=key[a],y=key[b];
          for(int o=0;o<2;o++){u64 c=o?(x|y):(x&y);
            if(find(c)>=0) continue;
            if(nf>=maxs){printf("OVERFLOW at k=%d\n",k);return 2;}
            key[nf]=c;lft[nf]=a;rgt[nf]=b;opc[nf]=o?'|':'&';lv[nf]=k;ins(c,nf);nf++;
            if(c==T && !getenv("DUMP")){printf("MIN %d\n",k);pr(nf-1);printf("\n");fflush(stdout);return 0;}
          }}}}
    end[k]=nf; printf("level %d: %u new (total %u)\n",k,end[k]-start[k],nf); fflush(stdout);
  }
  printf("NONE<=%d\n",K); if(getenv("DUMP")){FILE*fo=fopen(getenv("DUMP"),"w");for(uint32_t i=0;i<nf;i++)fprintf(fo,"%llx %d\n",(unsigned long long)key[i],lv[i]);fclose(fo);} return 1;
}
